class Counter {
  int _length = 0;
  List<int?> _buf = List.filled(2, null);
  int get capacity => _buf.length;

  void add(int v) {
    if (_length == _buf.length) {
      _buf = [..._buf, ...List<int?>.filled(_buf.length, null)];
    }
    _buf[_length++] = v;
  }
}

void main() {
  final c = Counter();
  for (var i = 0; i < 5; i++) {
    c.add(i);
  }
  print(c.capacity);
}
```

