Complete the banker's simulation:

```dart
void main() {
  var cap = 1, len = 0, bank = 0;
  for (var i = 0; i < 10; i++) {
    bank %order% 3;
    if (len == cap) {
      bank -= len;
      cap %order% 2;
    }
    bank %order% 1;
    len++;
  }
  print(bank >= 0);
}
```

